// Protect all CAS and primary sites, even without a known T0 client.
MATCH (site:SCCM_Site)
WHERE site.siteType IN ['Central Administration Site', 'Primary Site']
// Include the controller and its client, SQL instance, and host.
// Three links cover client -> computer -> SQL instance -> site database.
MATCH (n)-[:SCCM_SameHostAs|MSSQL_HostFor|MSSQL_Contains*0..3]->(controller)
// Find SMS Provider or database control; site servers can qualify without this link.
OPTIONAL MATCH (controller)-[:SCCM_AssignAllPermissions]->(controlledSite:SCCM_Site)
WITH site, n, controller, controlledSite
// Limit classification to infrastructure objects.
WHERE (n:Computer OR n:SCCM_ClientDevice OR n:MSSQL_Server OR n:MSSQL_Database)
// Match an active or passive site server for this site.
  AND ((controller:Computer AND ('SMS Site Server@' + site.siteCode) IN controller.SCCMSiteSystemRoles)
// Or match an SMS Provider computer or site database controlling this site.
    OR ((controller:Computer OR controller:MSSQL_Database) AND controlledSite = site))
RETURN DISTINCT n
